let lastUser;

export async function handler(event) {
  lastUser = event.userId;
  return { current: event.userId, previous: lastUser };
}

let client;
export const handler = async (event) => {
  client ??= createApiClient();
  // Safe to reuse the client
  const tenantId = event.headers['x-tenant-id'];
  // Do not cache tenant-specific mutable data globally
  return client.fetchForTenant(tenantId);
};

